package br.com.poolcontrol.financeiro.api;
import br.com.poolcontrol.financeiro.api.dto.ApprovalDecisionRequest; import br.com.poolcontrol.financeiro.domain.*; import br.com.poolcontrol.financeiro.repository.*; import br.com.poolcontrol.financeiro.service.ApprovalService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/financeiro/aprovacoes") @RequiredArgsConstructor public class ApprovalController { private final FinancialApprovalRepository approvals; private final ApprovalRuleRepository rules; private final ApprovalService service;
 @GetMapping List<FinancialApproval> list(){return approvals.findAll();} @PostMapping FinancialApproval create(@RequestBody FinancialApproval a){return approvals.save(a);} @PostMapping("/{id}/decidir") FinancialApproval decide(@PathVariable UUID id,@Valid @RequestBody ApprovalDecisionRequest r){return service.decide(id,r);} @GetMapping("/regras") List<ApprovalRule> rules(){return rules.findAll();} @PostMapping("/regras") ApprovalRule rule(@RequestBody ApprovalRule r){return rules.save(r);} }
